class Solution {
    bool subseq(const std::string& a, const std::string& b) {
        int i = 0;
        for (char c : b) if (i < (int)a.size() && a[i] == c) ++i;
        return i == (int)a.size();
    }
public:
    int findLUSlength(std::vector<std::string>& strs) {
        std::vector<int> ids(strs.size());
        std::iota(ids.begin(), ids.end(), 0);
        std::sort(ids.begin(), ids.end(), [&](int a, int b) {
            return strs[a].size() > strs[b].size();
        });
        for (int i : ids) {
            bool uncommon = true;
            for (int j = 0; j < (int)strs.size(); ++j) {
                if (i != j && strs[j].size() >= strs[i].size() &&
                    subseq(strs[i], strs[j])) { uncommon = false; break; }
            }
            if (uncommon) return strs[i].size();
        }
        return -1;
    }
};
